#include <cmath>
#include <iomanip>
#include <iostream>
#include <string>

#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// Initialize matrix A as in the original Polybench C code, then
// transform it into a symmetric positive semi-definite matrix A = L * L^T.
// A is laid out as A(j, i) == A[i][j] from the C code.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    Var i("i"), j("j");

    // ------------------------------------------------------------------
    // Step 1: Construct lower-triangular matrix with diagonal 1
    // ------------------------------------------------------------------
    //
    // C reference:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide buffer: A(j, i) corresponds to A[i][j].
    Func init_tri("init_tri");

    Expr val = cast<num_t>(-(j % n));                         // -(j % n)
    val = val / cast<num_t>(Expr(n)) + cast<num_t>(Expr(1));  // (-(j%n))/n + 1

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(Expr(0)));
    // Explicitly set the diagonal to 1.
    init_tri(i, i) = cast<num_t>(Expr(1));

    // Simple schedule: compute row-major, parallelize over rows,
    // vectorize over columns for better cache utilization and SIMD.
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, 8);

    // Realize directly into the provided buffer A.
    init_tri.realize(A);

    // ------------------------------------------------------------------
    // Step 2: Make the matrix positive semi-definite: B = A * A^T
    // ------------------------------------------------------------------
    //
    // C reference:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // Mapping to Halide buffer indices:
    //   B[r][s]          -> B_func(s, r)
    //   A[r][t]          -> A_param(t, r)
    //   A[s][t]          -> A_param(t, s)
    //
    // So: B_func(s, r) = sum_t A_param(t, r) * A_param(t, s).

    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(Expr(0));
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule for B = A * A^T:
    // - Tile in (s, r) for better locality.
    // - Parallelize outer tiles over rows (r).
    // - Vectorize across s within a tile.
    Var so("so"), ro("ro"), si("si"), ri("ri");
    const int tile_x = 32;
    const int tile_y = 32;

    B_func
        .compute_root()
        .tile(s, r, so, ro, si, ri, tile_x, tile_y)
        .parallel(ro)
        .vectorize(si, 8);

    // Apply a compatible schedule to the update step as well.
    B_func.update()
        .reorder(t, si, ri, so, ro)
        .parallel(ro)
        .vectorize(si, 8);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (we must not write A in-place during the
    // matmul because A_param reads from A).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // Convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code, and make it SPD.
    init_array(n, A);

    // ------------------------------------------------------------------
    // Build Halide helpers for the Cholesky factorization kernel
    // ------------------------------------------------------------------
    //
    // Original C kernel:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // The algorithm is inherently sequential in i and j because each
    // off-diagonal element in row i depends on previous elements of
    // the same row. To keep Halide's legality rules for reductions,
    // we express only the inner dot products (the sum over k) as
    // Halide pipelines, and orchestrate the loop over (i, j) in C++.
    //
    // For each off-diagonal A(j, i) (i fixed, j < i) we need:
    //   sum_ij = sum_{k=0}^{j-1} A[i][k] * A[j][k]
    //          = sum_{k=0}^{j-1} A(k, i) * A(k, j) in buffer indexing.
    //
    // For each diagonal A(i, i) we need:
    //   sum_ii = sum_{k=0}^{i-1} A[i][k] * A[i][k]
    //          = sum_{k=0}^{i-1} A(k, i)^2.

    ImageParam A_param_kernel(type_of<num_t>(), 2, "A_param_kernel");
    A_param_kernel.set(A);  // Shares storage with A; sees in-place updates.

    Param<int> i_param("i_param");
    Param<int> j_param("j_param");

    // Off-diagonal dot product: sum_{k=0}^{j-1} A_param_kernel(k, i) * A_param_kernel(k, j)
    RDom k_off(0, j_param, "k_off");
    Func off_dot("off_dot");
    off_dot() = cast<num_t>(Expr(0));
    off_dot() += A_param_kernel(k_off, i_param) * A_param_kernel(k_off, j_param);

    // Diagonal dot product: sum_{k=0}^{i-1} A_param_kernel(k, i)^2
    RDom k_diag(0, i_param, "k_diag");
    Func diag_dot("diag_dot");
    diag_dot() = cast<num_t>(Expr(0));
    diag_dot() += A_param_kernel(k_diag, i_param) * A_param_kernel(k_diag, i_param);

    // We keep the default schedule for these very small reduction
    // kernels. They are scalar (0-D) outputs, run many times but
    // cheap compared to the O(n^3) floating-point work of Cholesky.
    // We just JIT-compile them once before timing, so compilation
    // time doesn't pollute the measured kernel time.

    // Warm up JIT compilation outside the timed region.
    i_param.set(1);
    j_param.set(1);
    (void)off_dot.realize();
    (void)diag_dot.realize();

    // ------------------------------------------------------------------
    // Time the Cholesky factorization kernel.
    // ------------------------------------------------------------------
    auto start = std::chrono::high_resolution_clock::now();

    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute sum_{k=0}^{j-1} A(i,k) * A(j,k) using Halide.
            Halide::Buffer<num_t> off_buf = off_dot.realize();
            num_t sum_ij = off_buf();

            A(j, i) -= sum_ij;
            A(j, i) /= A(j, j);
        }

        // Diagonal element.
        // Compute sum_{k=0}^{i-1} A(i,k) * A(i,k) using Halide.
        Halide::Buffer<num_t> diag_buf = diag_dot.realize();
        num_t sum_ii = diag_buf();

        A(i, i) -= sum_ii;
        A(i, i) = static_cast<num_t>(
            std::sqrt(static_cast<double>(A(i, i))));
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
