#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// --------------------------------------------------------------------------------------
// Matrix initialization: identical math to the original Polybench C,
// but expressed and optimized as Halide pipelines.
// --------------------------------------------------------------------------------------

// Initialize matrix A as in the original Polybench C code.
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is laid out as A(j, i) == A[i][j] from the C code.
    Var i("i"), j("j");

    // ------------------------------------------------------------------
    // 1. Construct the lower-triangular matrix with diagonal 1,
    //    as in the original init_array.
    //
    // C code:
    //   for (i = 0; i < n; i++) {
    //     for (j = 0; j <= i; j++)
    //       A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //     for (j = i+1; j < n; j++)
    //       A[i][j] = 0;
    //     A[i][i] = 1;
    //   }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].
    // ------------------------------------------------------------------
    Func init_tri("init_tri");

    // Compute value: ((-j % n) / n) + 1, in num_t.
    Expr j_mod_n = j % n;
    Expr val = cast<num_t>(-j_mod_n);
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));
    // Explicitly set the diagonal to 1.
    init_tri(i, i) = cast<num_t>(1);

    // Realize into a temporary lower-triangular matrix L.
    Halide::Buffer<num_t, 2> L(n, n);
    init_tri.realize(L);

    // ------------------------------------------------------------------
    // 2. Make the matrix positive semi-definite:
    //
    // Original C:
    //   int r, s, t;
    //   B[r][s] = 0;
    //   for (t = 0; t < n; ++t)
    //     for (r = 0; r < n; ++r)
    //       for (s = 0; s < n; ++s)
    //         B[r][s] += A[r][t] * A[s][t];
    //   A[r][s] = B[r][s];
    //
    // This is B = A * A^T where A is n x n lower-triangular.
    //
    // We:
    //   - Treat L as the lower-triangular input.
    //   - Compute B(s, r) = sum_t L[r][t] * L[s][t] = L_param(t, r) * L_param(t, s).
    //   - Realize directly into A (the caller’s buffer).
    // ------------------------------------------------------------------
    ImageParam L_param(type_of<num_t>(), 2, "L_param");
    L_param.set(L);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    // L[r][t] -> L_param(t, r);  L[s][t] -> L_param(t, s)
    B_func(s, r) += L_param(t, r) * L_param(t, s);

    // -------------------------- Scheduling ----------------------------
    // We compute B at the root, parallelizing across rows and
    // vectorizing across columns. The reduction step is also
    // parallelized/vectorized over the pure (s, r) coordinates.
    Target target = get_host_target();
    const int vec_width = target.natural_vector_size(type_of<num_t>());

    B_func.compute_root()
          .parallel(r)
          .vectorize(s, vec_width > 0 ? vec_width : 1);

    // Schedule the reduction update (index 0) similarly.
    B_func.update(0)
          .parallel(r)
          .vectorize(s, vec_width > 0 ? vec_width : 1);

    // Realize the SPD matrix directly into A.
    B_func.realize(A);
}

// --------------------------------------------------------------------------------------
// Halide pipeline to compute the diagonal element update of Cholesky.
// For a given row/column index i, it computes:
//
//   A[i][i] = sqrt(A[i][i] - sum_{k=0}^{i-1} A[i][k]^2)
//
// With our mapping A(i,j) == A[row][col] -> A(col, row), this is:
//
//   A(i, i) = sqrt(A(i, i) - sum_{k=0}^{i-1} A(k, i)^2)
//
// We implement just this diagonal update as a scalar Halide reduction.
// --------------------------------------------------------------------------------------
struct CholeskyDiagPipeline {
    ImageParam A_in;   // current matrix state
    Param<int> i_param;
    Func diag;
    Target target;

    CholeskyDiagPipeline()
        : A_in(type_of<num_t>(), 2, "A_in"),
          i_param("i_param"),
          diag("cholesky_diag") {

        // Reduction domain k: 0 .. i_param-1
        RDom k(0, i_param, "k");

        // Base value is the current diagonal entry A(i, i).
        diag() = A_in(i_param, i_param);

        // Subtract the sum of squares of the current row entries A(k, i).
        diag() -= A_in(k, i_param) * A_in(k, i_param);

        // Final step: take square root, as in the original code:
        //   A[i][i] = SQRT_FUN(A[i][i]);
        // We cast via double to closely match the original numeric behavior.
        Expr as_double = cast<double>(diag());
        Expr root = Halide::sqrt(as_double);
        diag() = cast<num_t>(root);

        // Simple schedule: scalar reduction at root.
        diag.compute_root();

        target = get_host_target();
        diag.compile_jit(target);
    }

    // Compute the updated diagonal value for the given i, using the
    // current contents of buffer A_buf.
    num_t compute(Halide::Buffer<num_t, 2>& A_buf, int i) {
        A_in.set(A_buf);
        i_param.set(i);
        Halide::Buffer<num_t> out = diag.realize();
        return out();
    }
};

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

    // Initialize A as in the original Polybench code, using an
    // optimized Halide pipeline (triangular init + SPD transform).
    init_array(n, A);

    // Build the Halide pipeline for the diagonal update of Cholesky
    // outside the timed region so that JIT compilation time is not
    // included in the kernel timing.
    CholeskyDiagPipeline diag_pipeline;

    // Time the Cholesky factorization kernel.
    auto start = std::chrono::high_resolution_clock::now();

    // Main computational kernel translated directly, operating on the Buffer.
    //
    // Original C:
    //
    // for (i = 0; i < _PB_N; i++) {
    //   // j < i
    //   for (j = 0; j < i; j++) {
    //     for (k = 0; k < j; k++) {
    //       A[i][j] -= A[i][k] * A[j][k];
    //     }
    //     A[i][j] /= A[j][j];
    //   }
    //   // i == j case
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    // }
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[i][j]   -> A(j, i)
    //   A[i][k]   -> A(k, i)
    //   A[j][k]   -> A(k, j)
    //   A[j][j]   -> A(j, j)
    //   A[i][i]   -> A(i, i)
    //
    // We keep the row/column update loops in C++ (due to their
    // loop-carried dependencies across j and k), but:
    //   - We micro-optimize them for locality by working with
    //     contiguous row pointers.
    //   - We use a Halide reduction (diag_pipeline) for the diagonal
    //     update, which is the inner k-loop for A[i][i].
    //
    for (int i = 0; i < n; i++) {
        // Off-diagonal elements in row i: A(i,j) for 0 <= j < i.
        // In our storage, this is A(j, i) with j varying — contiguous
        // in memory when stepping in j.
        num_t* col_i = &A(0, i);  // pointer to row i (since x-dim is fast)

        for (int j = 0; j < i; j++) {
            num_t* col_j = &A(0, j);  // pointer to row j

            // Compute the inner product sum_{k=0}^{j-1} A[i][k] * A[j][k]
            // == sum_{k=0}^{j-1} A(k, i) * A(k, j).
            num_t sum = static_cast<num_t>(0);
            for (int k = 0; k < j; k++) {
                sum += col_i[k] * col_j[k];
            }

            // Update A[i][j] and divide by A[j][j].
            col_i[j] = (col_i[j] - sum) / col_j[j];  // col_j[j] == A(j, j)
        }

        // Diagonal element A[i][i].
        //
        // Original code:
        //   for (k = 0; k < i; k++)
        //     A[i][i] -= A[i][k] * A[i][k];
        //   A[i][i] = SQRT_FUN(A[i][i]);
        //
        // We compute this scalar in a Halide pipeline for better
        // vectorization and clear separation of concerns.
        A(i, i) = diag_pipeline.compute(A, i);
    }

    auto end = std::chrono::high_resolution_clock::now();
    auto duration = std::chrono::duration<long double>(end - start);

    // Optionally print the resulting lower-triangular matrix A,
    // similar to Polybench's print_array (only j <= i).
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int i = 0; i < n; i++) {
            for (int j = 0; j <= i; j++) {
                std::cerr << A(j, i) << '\n';
            }
        }
    }

    // Print elapsed time in seconds.
    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
