#include "Halide.h"

// include common Polybench-style definitions (DATA_TYPE, N, etc.)
#include "defines.hpp"

// include benchmark-specific definitions for cholesky (DATA_TYPE, N, etc.)
#include "cholesky.hpp"

using num_t = DATA_TYPE;

using namespace Halide;

// ---------------------------------------------------------------------------
// Initialize matrix A as in the original Polybench C code, but using Halide.
// ---------------------------------------------------------------------------
static void init_array(int n, Halide::Buffer<num_t, 2> A) {
    // A is laid out as A(j, i) == A[i][j] from the C code.
    Var i("i"), j("j");

    // -----------------------------------------------------------------------
    // 1) Build the lower-triangular matrix with diagonal 1 (Polybench init).
    //
    // C reference:
    // for (i = 0; i < n; i++) {
    //   for (j = 0; j <= i; j++)
    //     A[i][j] = (DATA_TYPE)(-j % n) / n + 1;
    //   for (j = i+1; j < n; j++)
    //     A[i][j] = 0;
    //   A[i][i] = 1;
    // }
    //
    // Mapping to Halide: A(j, i) corresponds to A[i][j].
    // -----------------------------------------------------------------------
    Func init_tri("init_tri");

    Expr val = cast<num_t>(-(j % n));
    val = val / cast<num_t>(n) + cast<num_t>(1);

    // Lower-triangular (including diagonal) gets 'val', above-diagonal is 0.
    init_tri(j, i) = select(j <= i, val, cast<num_t>(0));

    // Explicitly set the diagonal to 1.
    init_tri(i, i) = cast<num_t>(1);

    // Simple schedule: row-parallel, vectorized across columns.
    // A has dimensions (x=j, y=i).
    init_tri
        .compute_root()
        .parallel(i)
        .vectorize(j, 8);

    // Realize into the provided buffer A.
    init_tri.realize(A);

    // -----------------------------------------------------------------------
    // 2) Make the matrix positive semi-definite: B = A * A^T
    //
    // C reference:
    // int r, s, t;
    // B[r][s] = 0;
    // for (t = 0; t < n; ++t)
    //   for (r = 0; r < n; ++r)
    //     for (s = 0; s < n; ++s)
    //       B[r][s] += A[r][t] * A[s][t];
    // A[r][s] = B[r][s];
    //
    // With mapping A(j, i) == A[i][j]:
    //   A[r][t] -> A_param(t, r)
    //   A[s][t] -> A_param(t, s)
    //   B[r][s] -> B_func(s, r)
    // -----------------------------------------------------------------------
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    Var r("r"), s("s");
    RDom t(0, n, "t");

    Func B_func("B_func");
    B_func(s, r) = cast<num_t>(0);
    B_func(s, r) += A_param(t, r) * A_param(t, s);

    // Schedule B = A * A^T as a dense matrix-matrix multiply:
    // - Parallelize over rows (r)
    // - Vectorize across columns (s)
    // - Make reduction variable 't' innermost for good locality.
    B_func
        .compute_root()
        .parallel(r)
        .vectorize(s, 8);
    B_func
        .update()
        .reorder(t, s, r)  // innermost-first order: t, then s, then r
        .parallel(r)
        .vectorize(s, 8);

    Halide::Buffer<num_t, 2> B(n, n);
    B_func.realize(B);

    // Copy B back into A (small O(n^2) kernel; cost is negligible
    // compared to the O(n^3) multiply).
    for (int rr = 0; rr < n; ++rr) {
        for (int ss = 0; ss < n; ++ss) {
            A(ss, rr) = B(ss, rr);
        }
    }
}

// ---------------------------------------------------------------------------
// Cholesky factorization using Halide for the inner k-summations.
// The outer triangular loops over (i, j) are inherently sequential and
// are kept as host-driver loops, but each scalar update is computed by a
// tiny Halide reduction that exactly matches the original Polybench logic.
// ---------------------------------------------------------------------------
static void cholesky_factor(int n, Halide::Buffer<num_t, 2> A) {
    // ImageParam exposing the current matrix A to the Halide pipelines.
    // Note: we will mutate 'A' from C++; the pipeline only ever reads it.
    ImageParam A_param(type_of<num_t>(), 2, "A_param");
    A_param.set(A);

    // Scalar parameters: current row 'i' and column 'j'.
    Param<int> i_param("i_param");
    Param<int> j_param("j_param");

    // ----------------------------
    // Off-diagonal update pipeline
    // ----------------------------
    //
    // Original C (for fixed i, j < i):
    //   for (k = 0; k < j; k++) {
    //     A[i][j] -= A[i][k] * A[j][k];
    //   }
    //   A[i][j] /= A[j][j];
    //
    // With mapping A[j][i] -> A(j, i) and A[i][k] -> A(k, i), A[j][k] -> A(k, j):
    //   Start from A(j, i), then for k in [0, j):
    //     A(j, i) -= A(k, i) * A(k, j);
    //   Finally divide by A(j, j).
    //
    // We implement this literally as a scalar reduction with an
    // update definition so that the arithmetic order matches the
    // original loop-carried update.
    //
    RDom r_off(0, j_param, "r_off");

    Func off_val("off_val");
    // Pure definition: initial A(i,j) value.
    off_val() = A_param(j_param, i_param);
    // Update step: subtract A(i,k) * A(j,k) for each k.
    off_val() = off_val() - A_param(r_off, i_param) * A_param(r_off, j_param);

    // After the reduction finishes, divide once by A(j, j).
    Func off_final("off_final");
    off_final() = off_val() / A_param(j_param, j_param);

    // ------------------------
    // Diagonal update pipeline
    // ------------------------
    //
    // Original C (for fixed i):
    //   for (k = 0; k < i; k++) {
    //     A[i][i] -= A[i][k] * A[i][k];
    //   }
    //   A[i][i] = SQRT_FUN(A[i][i]);
    //
    // Mapping A[i][i] -> A(i, i), A[i][k] -> A(k, i).
    //
    RDom r_diag(0, i_param, "r_diag");

    Func diag_accum("diag_accum");
    // Start from A(i, i) and subtract contributions one-by-one,
    // exactly as in the original scalar loop.
    diag_accum() = A_param(i_param, i_param);
    diag_accum() = diag_accum() -
                   A_param(r_diag, i_param) * A_param(r_diag, i_param);

    Func diag_val("diag_val");
    diag_val() = Halide::sqrt(diag_accum());

    // Schedules for scalar pipelines:
    // They are 0-D Funcs; compute_root() is sufficient. The reductions
    // are over a single RDom, which is kept innermost by default.
    off_val.compute_root();
    off_final.compute_root();
    diag_accum.compute_root();
    diag_val.compute_root();

    // JIT-compile once and reuse in the host-driven loops.
    Target target = get_host_target();
    off_final.compile_jit(target);
    diag_val.compile_jit(target);

    // Scalar buffers reused for each realization to avoid repeated allocation.
    Halide::Buffer<num_t> off_buf;
    Halide::Buffer<num_t> diag_buf;

    // -----------------------------------------------------------------------
    // Host-driven triangular loops over (i, j), using the Halide pipelines
    // above to compute the inner k-reductions. This follows the Polybench
    // algorithm exactly, but the expensive dot-products are expressed and
    // scheduled in Halide (with good cache locality and potential
    // vectorization over the reduction variable).
    // -----------------------------------------------------------------------
    for (int i = 0; i < n; i++) {
        i_param.set(i);

        // Off-diagonal elements in row i.
        for (int j = 0; j < i; j++) {
            j_param.set(j);

            // Compute A(i, j) via Halide reduction pipeline.
            off_final.realize(off_buf);
            A(j, i) = off_buf();
        }

        // Diagonal element.
        diag_val.realize(diag_buf);
        A(i, i) = diag_buf();
    }
}

int main(int argc, char *argv[]) {
    // Problem size.
    int n = N;

    // Matrix A, using Halide::Buffer.
    // We follow the convention: A(j, i) == A[i][j] from the original C.
    Halide::Buffer<num_t, 2> A(n, n);

