    //   A[j][j] -> A(j, j)
    //   A[i][j] -> A(j, i)
    //   A[i][k] -> A(k, i)
    //   A[j][k] -> A(k, j)
    //
    // For a fixed column j, define
    //   S(i, j) = sum_{k=0}^{j-1} A[i][k] * A[j][k]
    //           = sum_{k=0}^{j-1} A(k, i) * A(k, j)
    //
    // Then:
    //   A[j][j] = sqrt( A[j][j] - S(j, j) );
    //   A[i][j] = (A[i][j] - S(i, j)) / A[j][j]  for i > j.
    //
    // For fixed j, all S(i, j) for i >= j depend only on columns < j,
    // so they can be computed in one Halide pipeline with no loop-carried
    // dependencies. We do this per column j and keep the outer j-loop on
    // the host to preserve the exact Cholesky semantics.
    // -------------------------------------------------------------------------

    // Parameters and Vars for the dot-product pipeline.
    ImageParam A_param(type_of<num_t>(), 2, "A_param_chol");
    A_param.set(A);  // points at the same storage as A (updated in-place)
    Param<int> j_param("j_param");
