    RDom k_dot(0, j_param, "k_dot");

    // dot_col(i) = sum_{k=0}^{j-1} A(k, i) * A(k, j)
    Func dot_col("dot_col");
    dot_col(i_var) = cast<num_t>(0);
    dot_col(i_var) += A_param(k_dot, i_var) * A_param(k_dot, j_param);

    // Simple, robust schedule:
    //  - compute_root: global loop nest reused across all j
    //  - vectorize across i_var (rows) for good SIMD utilization
    const int vec_width = 8;
